let lang="en", currentModule=null, quizIndex=0, score=0, answered=false;
const $=id=>document.getElementById(id);
function applyLanguage(next){lang=next;document.documentElement.lang=lang;document.querySelectorAll("[data-i18n]").forEach(el=>{const k=el.dataset.i18n;if(translations[lang][k])el.textContent=translations[lang][k]});renderGlossary();if(currentModule)renderLesson(currentModule);renderQuiz();}
$("language").addEventListener("change",e=>applyLanguage(e.target.value));
$("themeToggle").addEventListener("click",()=>document.body.classList.toggle("dark"));
const moduleKeys=["first-day","safety","workflow","quality","german","rights"];
function completed(){try{return JSON.parse(localStorage.getItem("wr-completed")||"[]")}catch(e){return []}}
function updateProgress(){const done=completed();$("progressText").textContent=`${done.length} / 6`; $("progressBar").style.width=(done.length/6*100)+"%";document.querySelectorAll(".module-card").forEach(c=>c.classList.toggle("completed",done.includes(c.dataset.module)));document.querySelectorAll(".module-card").forEach(c=>{const s=c.querySelector(".module-link");if(done.includes(c.dataset.module))s.textContent=lang==="de"?"✓ Erledigt · Lektion öffnen →":"✓ Completed · Open lesson →";});}
function renderLesson(key){currentModule=key;const l=lessons[key];const i=lang==="de"?1:0;let html=`<h2>${l.title[i]}</h2><p>${l.intro[i]}</p>`;for(const s of l.sections){html+=`<h3>${s[i]}</h3><ul>${s[2].map(t=>`<li>${t}</li>`).join("")}</ul>`} $("lessonContent").innerHTML=html;$("lessonArea").hidden=false;const done=completed().includes(key);$("markComplete").textContent=done?(lang==="de"?"✓ Bereits erledigt":"✓ Completed"):(lang==="de"?"Als erledigt markieren ✓":"Mark as completed ✓");$("lessonStatus").textContent=done?(lang==="de"?"Fortschritt gespeichert":"Progress saved"):"";$("lessonArea").scrollIntoView({behavior:"smooth",block:"start"});}
// Navigate each learning module to its separate HTML webpage

document.querySelectorAll(".module-card").forEach(c => {

  c.addEventListener("click", () => {

    const lessonPages = {

      "first-day": "lesson-01.html",

      "safety": "lesson-02.html",

      "workflow": "lesson-03.html",

      "quality": "lesson-04.html",

      "german": "lesson-05.html",

      "rights": "lesson-06.html"

    };

    const page = lessonPages[c.dataset.module];

    if (page) {

      window.location.href = "./" + page;

      return;

    }

    renderLesson(c.dataset.module);

  });

});
$("closeLesson").addEventListener("click",()=>{$("lessonArea").hidden=true;currentModule=null;});
$("markComplete").addEventListener("click",()=>{if(!currentModule)return;let done=completed();if(!done.includes(currentModule))done.push(currentModule);localStorage.setItem("wr-completed",JSON.stringify(done));updateProgress();$("markComplete").textContent=lang==="de"?"✓ Erledigt":"✓ Completed";$("lessonStatus").textContent=lang==="de"?"Fortschritt gespeichert":"Progress saved";});
function renderQuiz(){const q=quiz[quizIndex];$("quizCount").textContent=(lang==="de"?"Frage ":"Question ")+(quizIndex+1)+(lang==="de"?" von 5":" of 5");$("quizScore").textContent=quizIndex===quiz.length-1&&answered?(lang==="de"?`Ergebnis: ${score}/5`:`Score: ${score}/5`):"";$("quizBar").style.width=((quizIndex+1)/quiz.length*100)+"%";$("questionText").textContent=q.q[lang==="de"?1:0];$("answerOptions").innerHTML="";$("feedback").textContent="";$("nextQuestion").disabled=true;$("nextQuestion").textContent=quizIndex===quiz.length-1?(lang==="de"?"Ergebnis ansehen →":"See result →"):(lang==="de"?"Nächste Frage →":"Next question →");answered=false;q.a.forEach((a,i)=>{const b=document.createElement("button");b.className="answer-option";b.textContent=a[lang==="de"?1:0];b.addEventListener("click",()=>chooseAnswer(i));$("answerOptions").appendChild(b);});}
function chooseAnswer(i){if(answered)return;answered=true;const q=quiz[quizIndex];document.querySelectorAll(".answer-option").forEach((b,j)=>{b.disabled=true;if(j===q.correct)b.classList.add("correct");if(j===i&&i!==q.correct)b.classList.add("incorrect")});if(i===q.correct)score++;$("feedback").textContent=q.why[lang==="de"?1:0];$("nextQuestion").disabled=false;$("quizScore").textContent=(lang==="de"?"Punkte: ":"Score: ")+score;}
$("nextQuestion").addEventListener("click",()=>{if(!answered)return;if(quizIndex<quiz.length-1){quizIndex++;renderQuiz()}else{$("questionText").textContent=lang==="de"?`Du hast ${score} von 5 Punkten erreicht.`:`You scored ${score} out of 5.`;$("answerOptions").innerHTML="";$("feedback").textContent=lang==="de"?"Wiederhole die Module, wenn du unsicher bist. Dies ist kein offizieller Sicherheitstest.":"Review the modules if you were unsure. This is not an official safety assessment.";$("nextQuestion").disabled=true;$("quizScore").textContent=(lang==="de"?"Ergebnis: ":"Final score: ")+score+"/5";}});
$("restartQuiz").addEventListener("click",()=>{quizIndex=0;score=0;answered=false;renderQuiz()});
function renderGlossary(){const words=[["die Schicht","shift"],["die Pause","break"],["der Wareneingang","goods receiving"],["der Warenausgang","goods dispatch"],["die Bestellung","order"],["der Lagerbestand","stock / inventory"],["die Sicherheitsweste","high-visibility vest"],["die Beschädigung","damage"],["die Arbeitsanweisung","work instruction"],["die Führungskraft","supervisor / manager"]];$("glossary").innerHTML=words.map(w=>`<div><strong>${w[0]}</strong><span>${lang==="de"?({"shift":"Schicht","break":"Pause","goods receiving":"Wareneingang","goods dispatch":"Warenausgang","order":"Bestellung","stock / inventory":"Lagerbestand","high-visibility vest":"Warnweste","damage":"Beschädigung","work instruction":"Arbeitsanweisung","supervisor / manager":"Führungskraft"}[w[1]]):w[1]}</span></div>`).join("")}
updateProgress();renderQuiz();
